extern s32 stopSoundLocked(s32); extern void rampSoundChannelLocked(s32,s32,s32); extern s32 gMenuSoundHandle; extern u8 sOptionScaleY,sOptionScaleX;
/* Applies the X/Y option scales (0-10) as 0-127 levels on sound channels 253/254, then stops the menu sound if one is playing. */ void applyVolumeOptions(void) { u32 volume; u8 level; volume=sOptionScaleX*0x7f; level=volume/10; rampSoundChannelLocked(level&255,1000,253); volume=sOptionScaleY*0x7f; level=volume/10; rampSoundChannelLocked(level&255,1000,254); if(gMenuSoundHandle!=-1) { stopSoundLocked(gMenuSoundHandle); gMenuSoundHandle=-1; } }
